mapper.select:
select r.id , r.order_no 'orderNo' , r.venue_id 'venueId' , v.name 'venueName' , v.location 'venueLocation'
, r.reserve_date 'reservationDate', case r.status when 1 then '已预约' when 2 then '已取消' when 3 then '已过期' else '未知' end 'statusDesc'
,v.create_time 'createTime', t.label 'slotLabel', t.start_time 'startTime' , t.end_time 'endTime'
from reservation r
left join venue v on r.venue_id = v.id
left join time_slot t on r.slot_id = t.id


        and r.user_id = #{dto.userId}


        and r.venue_id = #{dto.venueId}


        and r.status = #{dto.status}


        and r.reserve_date = #{dto.reserveDate}


order by r.create_time desc
